":"c6cbdb10ed01aa9daf1394952ce956dac24626cccf9a4d3fb343c367300b87a9","objectiveCode":"g8-irregular-plural","grade":8,"evidenceFocusId":"6bb96761-cc66-4b15-8ee6-7f433ce06d28","mappingRole":"primary","status":"proposed"},{"questionId":"fef1c766-52f1-4160-b10d-16453d9870cb","questionContentHash":"5bbfbc96c18735e6c95a4b00f74416e4d3b037c9bca59fda8818e7a4640f9450","objectiveCode":"g8-emphatic-present","grade":8,"evidenceFocusId":"8e604b48-a543-4785-8383-e2294307aded","mappingRole":"primary","status":"proposed"},{"questionId":"ff484616-3e3b-569d-aa7e-327ae1da3990","questionContentHash":"df442bf56d81055bf0dda5fdf2279bc705c9abc6d711bb8eae0cc0b7c86e718a","objectiveCode":"g7-was-were","grade":7,"evidenceFocusId":"764ebaa8-0074-49c7-a686-8ce21d668138","mappingRole":"primary","status":"proposed"},{"questionId":"ff484616-3e3b-569d-aa7e-327ae1da3990","questionContentHash":"df442bf56d81055bf0dda5fdf2279bc705c9abc6d711bb8eae0cc0b7c86e718a","objectiveCode":"g8-was-were","grade":8,"evidenceFocusId":"764ebaa8-0074-49c7-a686-8ce21d668138","mappingRole":"primary","status":"proposed"},{"questionId":"ff49bc74-1087-5843-8885-7799302cf238","questionContentHash":"57cbb52a329566bd8eb93a2b31ee6a0e590cf726f4a5f0f79856ffeb944f8d9e","objectiveCode":"g7-prepositions-time","grade":7,"evidenceFocusId":"f51313a6-9c54-4b2c-ac3a-e4d83becf0f7","mappingRole":"primary","status":"proposed"},{"questionId":"ff49bc74-1087-5843-8885-7799302cf238","questionContentHash":"57cbb52a329566bd8eb93a2b31ee6a0e590cf726f4a5f0f79856ffeb944f8d9e","objectiveCode":"g8-prepositions-time","grade":8,"evidenceFocusId":"f51313a6-9c54-4b2c-ac3a-e4d83becf0f7","mappingRole":"primary","status":"proposed"},{"questionId":"ff4d9e2b-90a1-b3a0-324e-71980871f44a","questionContentHash":"336d4e5212dfe397c681582b1b47df5412128824ea188aeb440cae528be38752","objectiveCode":"g7-uncertain-past-possibility","grade":7,"evidenceFocusId":"032a2885-ffdc-499e-8736-7955f487bca9","mappingRole":"primary","status":"proposed"},{"questionId":"ff594aa0-2447-464d-b943-997750680941","questionContentHash":"e87d056080a8463f19db0c4d590e46403ab331039bfa91e93d38df9db205f598","objectiveCode":"g8-dependent-preposition-sets","grade":8,"evidenceFocusId":"d4a41c1c-60f1-4341-aeb1-8e647ea638cf","mappingRole":"primary","status":"proposed"},{"questionId":"ff6ad40b-17ec-9848-db6c-2a77c1bdd7ec","questionContentHash":"a6c14c411aef2d2cfa53cc4ebb1542a7719f7230854ef2ca070402296793fc9c","objectiveCode":"g7-must-have-deduction","grade":7,"evidenceFocusId":"b394994b-1ec7-4d46-bf82-9bddde1e5ebe","mappingRole":"primary","status":"proposed"},{"questionId":"ff6e37c9-ab8e-41ff-a8da-7c1888c82879","questionContentHash":"ffdb2dc304777ec6ed95d5e11d316d6ccf489a338a40ecbf2bb5f0c1823697fe","objectiveCode":"g7-present-perfect-form","grade":7,"evidenceFocusId":"cb4efb03-f250-439f-bf3d-db31f907a85e","mappingRole":"primary","status":"proposed"},{"questionId":"ff929a33-df4e-483e-1f53-8b077915d4d7","questionContentHash":"62d1795512d248b856433d657680d82c9c99f30a0762e010f0e08285eaee8b13","objectiveCode":"g7-second-conditional-result","grade":7,"evidenceFocusId":"8d0a7c17-0748-46a1-921c-d43bd272e3db","mappingRole":"primary","status":"proposed"},{"questionId":"ff929a33-df4e-483e-1f53-8b077915d4d7","questionContentHash":"62d1795512d248b856433d657680d82c9c99f30a0762e010f0e08285eaee8b13","objectiveCode":"g8-second-conditional-result","grade":8,"evidenceFocusId":"8d0a7c17-0748-46a1-921c-d43bd272e3db","mappingRole":"primary","status":"proposed"},{"questionId":"ffc4d1ab-d181-4eaa-b127-70df5404f21f","questionContentHash":"b3b7a64299b87a2acd9ae8f8d73fe442cedcca3854d6cc1c18b7545c2e956f36","objectiveCode":"g7-adjective-position","grade":7,"evidenceFocusId":"65c45a78-91c4-48f4-b805-9e61ed2d6f8e","mappingRole":"primary","status":"proposed"},{"questionId":"ffc4dc58-ca62-1c98-9156-1901e3afaf08","questionContentHash":"fe18db3a65ae8149a57c245b4e6ba0d924306b55597c559e61c6cf3dfa4f1151","objectiveCode":"g8-reported-can","grade":8,"evidenceFocusId":"c1cfb620-44b6-480e-b9e2-0c6e5bea67c0","mappingRole":"primary","status":"proposed"}]}'::jsonb; v_version uuid:=md5('bh-english-objectives:2026-editorial-2')::uuid; v_framework uuid:=md5('bh-english-objectives:framework')::uuid; v_subject uuid; v_fs uuid:=md5('bh-english-objectives:2026-editorial-2:english')::uuid; g integer; v_stage uuid; v_scope uuid; v_node uuid; o jsonb; v_focus_id text;
begin
 if exists(select 1 from public.curriculum_framework_versions where id=v_version) then raise notice 'Editorial draft exists; no content overwritten';return;end if;
 if exists(select 1 from jsonb_array_elements(p->'mappings') m where not exists(select 1 from public.questions q where q.id=(m->>'questionId')::uuid and q.current_content_hash=m->>'questionContentHash' and q.verified_content_hash=q.current_content_hash and q.verification_status='verified' and q.is_active and q.pool_scope='global' and (m->>'grade')::smallint=any(q.eligible_grade_levels))) then raise exception 'editorial_source_questions_changed';end if;
 if exists(select 1 from jsonb_array_elements(p->'mappings') m where not exists(select 1 from public.verified_question_registry_taxonomy tx where tx.question_id=(m->>'questionId')::uuid and tx.question_content_hash=m->>'questionContentHash' and tx.evidence_focus_id=(m->>'evidenceFocusId')::uuid and tx.review_status='approved' and not tx.human_review_required)) then raise exception 'editorial_source_taxonomy_changed';end if;
 if exists(select 1 from jsonb_array_elements(p->'sourceFocuses') f where not exists(select 1 from public.academic_skill_evidence_focuses ef where ef.id=(f->>'id')::uuid and ef.name=f->>'name' and ef.code=f->>'code' and ef.status='active')) then raise exception 'editorial_source_focus_definitions_changed';end if;
 select id into strict v_subject from public.academic_subjects where code='english' and is_active;
 insert into public.curriculum_framework_versions(id,framework_id,version_code,display_name,source_version,source_uri,source_license,status,release_notes) values(v_version,v_framework,'2026-editorial-2','English recognition objectives — consolidated review draft','bh-english-core-v1', 'repository:content/english-curriculum-repair/editorial/review-package.json','Brains Heist original educational content','draft','Partial recognition-only editorial proposal; source manifest SHA-256: '||(p->>'sourceHash')||'. Focus links and question mappings require governed review. No school adoption.');
 insert into public.curriculum_framework_subjects(id,framework_version_id,academic_subject_id,code,name) values(v_fs,v_version,v_subject,'english','English');
 foreach g in array array[7,8] loop
 v_stage:=md5(v_version::text||':grade:'||g)::uuid;v_scope:=md5(v_version::text||':scope:'||g)::uuid;v_node:=md5(v_scope::text||':recognition')::uuid;
 insert into public.curriculum_stages(id,framework_version_id,code,name,sequence_number) values(v_stage,v_version,'grade-'||g,'Grade '||g,g);
 insert into public.curriculum_scopes(id,framework_version_id,framework_subject_id,stage_id,academic_subject_id,code,name,sequence_number,coverage_status) values(v_scope,v_version,v_fs,v_stage,v_subject,'english-grade-'||g,'English · Grade '||g||' · Recognition review draft',g,'partial');
 insert into public.curriculum_nodes(id,framework_version_id,curriculum_scope_id,node_type,code,name,depth,sequence_number) values(v_node,v_version,v_scope,'strand','recognition','English recognition and interpretation',0,1);
 for o in select value from jsonb_array_elements(p->'objectives') where (value->>'grade')::integer=g loop
 insert into public.curriculum_objectives(id,framework_version_id,curriculum_scope_id,curriculum_node_id,code,statement,objective_type,is_assessable,assessment_boundary) values(md5(v_version::text||':'||(o->>'code'))::uuid,v_version,v_scope,v_node,o->>'code',o->>'statement','skill',true,o->>'assessmentBoundary');
 for v_focus_id in select jsonb_array_elements_text(o->'evidenceFocusIds') loop
 insert into private.curriculum_objective_focus_links(objective_id,framework_version_id,evidence_focus_id,review_status,rationale) values(md5(v_version::text||':'||(o->>'code'))::uuid,v_version,v_focus_id::uuid,'proposed','Editorial consolidation proposal for '||(o->>'code')||'; requires review against exact source questions and recognition boundary.');
 end loop;end loop;end loop;
end;
$editorial$;
